def append_qa(bank):
 for line in QA.strip().splitlines():
  n,q,a,src=line.split('|');kind,anchor=src.split(':',1);bank[int(n)-1].append({'q':q,'a':a,'basis':kind,'anchor':anchor})
 return bank

def append_mcq(bank):
 for line in MCQ.strip().splitlines():
  n,q,a,w1,w2,w3,why,hint,src=line.split('|');kind,anchor=src.split(':',1);bank[int(n)-1].append({'q':q,'a':a,'wrong':[w1,w2,w3],'why':why,'hint':hint,'basis':kind,'anchor':anchor})
 return bank
